const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id),ui={overlay:$('overlay'),modal:$('modal'),score:$('score'),best:$('best'),distance:$('distance'),boostFill:$('boostFill'),boostBtn:$('boostBtn'),mobileBoost:$('mobileBoost'),pause:$('pauseBtn')};
const savedBest=Number(localStorage.getItem('neonDriftBest')||0);let best=savedBest,state='ready',lane=0,playerLane=0,score=0,meters=0,speed=30,energy=0,boosting=false,spawnIn=1,objects=[],particles=[],shake=0,flash=0,last=0,worldTime=0,soundOn=false,audio=null;
let W=0,H=0,dpr=1,stars=[],buildings=[];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),fmt=n=>String(Math.floor(n)).padStart(5,'0');
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);stars=Array.from({length:75},()=>({x:Math.random()*W,y:Math.random()*H*.48,r:Math.random()*1.5+.25,a:Math.random()*.55+.15,phase:Math.random()*6}));buildings=[];let x=-8;while(x<W+20){let w=rand(22,70),h=rand(H*.1,H*.33);buildings.push({x,w,h,seed:Math.random(),rows:Math.floor(h/10),cols:Math.floor(w/9)});x+=w+rand(3,10)}}
new ResizeObserver(resize).observe(canvas);resize();
function showOverlay(kind){ui.overlay.classList.remove('hidden');if(kind==='ready'){ui.modal.innerHTML='<div class="modal-kicker">THE CITY NEVER SLEEPS</div><h2>OWN THE<br><span style="color:#62f0ff">NIGHT RUN.</span></h2><p>Thread the neon traffic, grab energy sparks, and see how far your rig can go. The road gets faster the longer you survive.</p><button class="primary" id="startBtn">START YOUR RUN&nbsp; →</button><p class="modal-note">MOVE: ← → OR A / D &nbsp;·&nbsp; BOOST: HOLD SPACE</p>';}
else if(kind==='pause'){ui.modal.innerHTML='<div class="modal-kicker">RUN PAUSED</div><h2>TAKE A<br><span style="color:#62f0ff">BREATHER.</span></h2><p>Your run is saved right where you left it. Ready to get back out there?</p><button class="primary" id="resumeBtn">RESUME RUN&nbsp; →</button><p class="modal-note">PRESS ESC OR P TO RESUME</p>';}
else{ui.modal.innerHTML='<div class="modal-kicker">RUN COMPLETE</div><h2>YOU OWNED<br><span style="color:#ff5ca8">THE NIGHT.</span></h2><div class="result"><div><strong>'+fmt(score)+'</strong><span>FINAL SCORE</span></div><div><strong>'+Math.floor(meters)+'m</strong><span>DISTANCE</span></div><div><strong>'+fmt(best)+'</strong><span>BEST</span></div></div><p>The city is still out there. One more run?</p><button class="primary" id="startBtn">RUN IT BACK&nbsp; →</button><p class="modal-note">TAP OR PRESS ENTER TO PLAY AGAIN</p>';}
const start=$('startBtn'),resume=$('resumeBtn');if(start)start.onclick=startGame;if(resume)resume.onclick=resumeGame;}
function startGame(){state='playing';lane=0;playerLane=0;score=0;meters=0;speed=30;energy=0;boosting=false;spawnIn=.8;objects=[];particles=[];shake=0;flash=0;ui.overlay.classList.add('hidden');ui.pause.textContent='Ⅱ';updateHud();}
function pauseGame(){if(state!=='playing')return;state='paused';boosting=false;ui.pause.textContent='▶';showOverlay('pause')}
function resumeGame(){if(state!=='paused')return;state='playing';ui.pause.textContent='Ⅱ';ui.overlay.classList.add('hidden');last=performance.now()}
function endGame(){if(state!=='playing')return;state='over';boosting=false;if(score>best){best=score;localStorage.setItem('neonDriftBest',best)}updateHud();showOverlay('over')}
function updateHud(){ui.score.textContent=fmt(score);ui.best.textContent=fmt(best);ui.distance.innerHTML=Math.floor(meters)+'<span style="font-size:11px;color:#91a5c2"> m</span>';ui.boostFill.style.width=energy+'%';const ready=energy>2;ui.boostBtn.classList.toggle('ready',ready);ui.mobileBoost.classList.toggle('ready',ready);ui.boostBtn.disabled=!ready;ui.mobileBoost.disabled=!ready}
function move(dir){if(state==='ready'||state==='over'){startGame();return}if(state!=='playing')return;lane=clamp(lane+dir,-1,1);}
function setBoost(on){boosting=!!on&&state==='playing'&&energy>1}
function addObject(type,laneNum,d){objects.push({type,lane:laneNum,d,spin:Math.random()*6,hit:false})}
function spawn(){let laneNum=Math.floor(Math.random()*3)-1,typeRoll=Math.random();if(typeRoll<.25){addObject('spark',laneNum,93);if(Math.random()<.38)addObject('spark',clamp(laneNum+(Math.random()<.5?-1:1),-1,1),108)}else{addObject(typeRoll<.62?'barrier':'drone',laneNum,93);if(Math.random()<.18)addObject('spark',Math.floor(Math.random()*3)-1,111)}spawnIn=rand(.62,1.05)*Math.max(.63,1-(speed-30)*.009)}

