function spawn(){let laneNum=Math.floor(Math.random()*3)-1,typeRoll=Math.random();if(typeRoll<.25){addObject('spark',laneNum,93);if(Math.random()<.38)addObject('spark',clamp(laneNum+(Math.random()<.5?-1:1),-1,1),108)}else{addObject(typeRoll<.62?'barrier':'drone',laneNum,93);if(Math.random()<.18)addObject('spark',Math.floor(Math.random()*3)-1,111)}spawnIn=rand(.62,1.05)*Math.max(.63,1-(speed-30)*.009)}
function poly(points,fill,stroke=null,lw=1){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function roadPoint(t){const half=W*(.045+.425*t);return{y:H*.39+(H*.69)*t,x:W*.5,half}}
function drawBackground(){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#101831');sky.addColorStop(.48,'#292744');sky.addColorStop(.72,'#af4c79');sky.addColorStop(1,'#ff9b72');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
const glow=ctx.createRadialGradient(W*.5,H*.43,2,W*.5,H*.43,W*.46);glow.addColorStop(0,'#ffc07988');glow.addColorStop(.35,'#f5787770');glow.addColorStop(1,'#f5787700');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.8);
for(const s of stars){ctx.globalAlpha=s.a*(.65+.35*Math.sin(worldTime*1.1+s.phase));ctx.fillStyle='#d5efff';ctx.fillRect(s.x,s.y,s.r,s.r)}ctx.globalAlpha=1;
const horizon=H*.43;ctx.fillStyle='#22233a';for(const b of buildings){const x=b.x,y=horizon-b.h;ctx.fillRect(x,y,b.w,b.h+2);ctx.fillStyle='#38314e';ctx.fillRect(x+4,y+5,Math.max(3,b.w-8),2);ctx.fillStyle='#f9b46b';for(let r=0;r<b.rows;r++)for(let c=0;c<b.cols;c++){if(Math.sin((r+1)*17+(c+1)*31+b.seed*100)>.13){ctx.globalAlpha=.35+Math.sin(worldTime*1.3+r+c+b.seed)*.1;ctx.fillRect(x+5+c*9,y+13+r*10,2.4,3.2)}}ctx.globalAlpha=1;ctx.fillStyle='#22233a'}
ctx.fillStyle='#ffae74';ctx.fillRect(0,horizon,W,1.5);
// roadside glow and distant city haze
const haze=ctx.createLinearGradient(0,horizon-20,0,horizon+65);haze.addColorStop(0,'#ff7b8270');haze.addColorStop(1,'#ff7b8200');ctx.fillStyle=haze;ctx.fillRect(0,horizon-20,W,85);
}
function drawRoad(){const top=roadPoint(0),bottom=roadPoint(1);poly([[top.x-top.half,top.y],[top.x+top.half,top.y],[bottom.x+bottom.half,bottom.y],[bottom.x-bottom.half,bottom.y]],'#131a2d','#f69aaf66',1);
poly([[top.x-top.half,top.y],[top.x-top.half+W*.012,top.y],[bottom.x-bottom.half+W*.024,bottom.y],[bottom.x-bottom.half,bottom.y]],'#ff4f8e22');poly([[top.x+top.half-W*.012,top.y],[top.x+top.half,top.y],[bottom.x+bottom.half,bottom.y],[bottom.x+bottom.half-W*.024,bottom.y]],'#ff4f8e22');
// sweeping lane dashes recede into the horizon
for(let side of [-1,1]){for(let i=0;i<18;i++){let p=((i/18+worldTime*(speed/190))%1);let t=p*p;let q=roadPoint(t);let x=q.x+side*q.half/3;let len=2+26*t;ctx.globalAlpha=.16+.55*t;ctx.strokeStyle='#7edff5';ctx.lineWidth=1+2*t;ctx.beginPath();ctx.moveTo(x,q.y-len/2);ctx.lineTo(x,q.y+len/2);ctx.stroke()}ctx.globalAlpha=1}
// road center perspective bars
for(let i=0;i<13;i++){const p=((i/13+worldTime*(speed/230))%1),t=p*p,q=roadPoint(t);ctx.globalAlpha=.035+.09*t;ctx.strokeStyle='#d7efff';ctx.lineWidth=1+t;ctx.beginPath();ctx.moveTo(q.x-q.half,q.y);ctx.lineTo(q.x+q.half,q.y);ctx.stroke()}ctx.globalAlpha=1;
// edge reflectors
for(let i=0;i<16;i++){const p=((i/16+worldTime*(speed/165))%1),t=p*p,q=roadPoint(t);for(const side of [-1,1]){ctx.globalAlpha=.28+.6*t;ctx.fillStyle=side<0?'#62f0ff':'#ff5ca8';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10*t+2;ctx.fillRect(q.x+side*(q.half+2),q.y-2-4*t,2+3*t,2+4*t)}}ctx.shadowBlur=0;ctx.globalAlpha=1}
function project(o){const t=clamp(1-o.d/100,0,1),q=roadPoint(t),x=q.x+o.lane*q.half*.57;return{x,y:q.y,scale:.16+t*1.08,t}}
function drawSpark(o,p){const s=13*p.scale,a=worldTime*3+o.spin;ctx.save();ctx.translate(p.x,p.y-17*p.scale);ctx.rotate(a);ctx.shadowColor='#69f8ff';ctx.shadowBlur=20*p.scale+4;poly([[0,-s],[s*.68,0],[0,s],[s*-.68,0]],'#b9ffff','#36dff5',2*p.scale);ctx.shadowBlur=0;ctx.restore();ctx.globalAlpha=.15;ctx.fillStyle='#62f0ff';ctx.beginPath();ctx.ellipse(p.x,p.y,13*p.scale,4*p.scale,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function drawBarrier(p){const s=p.scale,w=38*s,h=28*s,x=p.x,y=p.y;ctx.fillStyle='#050a16aa';ctx.beginPath();ctx.ellipse(x,y+3*s,w*.75,7*s,0,0,Math.PI*2);ctx.fill();poly([[x-w*.5,y-h],[x+w*.5,y-h],[x+w*.38,y],[x-w*.38,y]],'#492a4d','#ff6da5',1.5*s);poly([[x-w*.5,y-h],[x-w*.25,y-h-7*s],[x+w*.68,y-h-7*s],[x+w*.5,y-h]],'#b94978','#ff9cba',1*s);for(let i=0;i<3;i++){ctx.strokeStyle=i%2?'#ffcf68':'#ff668e';ctx.lineWidth=3*s;ctx.beginPath();ctx.moveTo(x-w*.38+i*12*s,y-h+5*s);ctx.lineTo(x-w*.29+i*10*s,y-3*s);ctx.stroke()}ctx.fillStyle='#ffcf68';ctx.shadowColor='#ff668e';ctx.shadowBlur=10*s;ctx.fillRect(x-w*.45,y-h-3*s,w*.9,2*s);ctx.shadowBlur=0}
function drawDrone(p){const s=p.scale,x=p.x,y=p.y-16*s;ctx.save();ctx.translate(x,y+Math.sin(worldTime*5)*3*s);ctx.shadowColor='#ff4fa6';ctx.shadowBlur=18*s;poly([[-21*s,0],[-13*s,-8*s],[13*s,-8*s],[21*s,0],[14*s,9*s],[-14*s,9*s]],'#401c46','#ff62bc',1.5*s);poly([[-8*s,-7*s],[0,-14*s],[8*s,-7*s]],'#72f8ff','#baffff',1*s);ctx.fillStyle='#ff5ca8';ctx.fillRect(-18*s,10*s,8*s,2*s);ctx.fillRect(10*s,10*s,8*s,2*s);ctx.restore();ctx.shadowBlur=0}

