function playTone(freq,duration=.08,type='sine'){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch(e){}}
function update(dt){worldTime+=dt;if(state!=='playing'){if(state==='ready')speed=30;return}const multiplier=boosting&&energy>0?1.65:1;speed=Math.min(62,30+meters*.075);if(boosting&&energy>0){energy=Math.max(0,energy-34*dt);if(energy===0)boosting=false}else boosting=false;const actualSpeed=speed+(boosting?18:0);meters+=actualSpeed*dt;score+=Math.floor(actualSpeed*dt*1.35);playerLane+=(lane-playerLane)*Math.min(1,dt*11);spawnIn-=dt;if(spawnIn<=0)spawn();
for(const o of objects){const before=o.d;o.d-=actualSpeed*dt;if(before>4&&o.d<=4&&!o.hit){o.hit=true;if(o.type==='spark'){score+=150;energy=Math.min(100,energy+21);const p=project(o);burst(p.x,p.y-18*p.scale,'#6bf5ff');playTone(720,.12,'triangle')}else if(Math.abs(lane-o.lane)<.5){shake=10;flash=.3;playTone(90,.32,'sawtooth');endGame();break}}}
objects=objects.filter(o=>o.d>-4);if(state==='playing'){if(boosting){score+=Math.floor(20*dt);if(Math.random()<dt*14)particles.push({x:W*.5+rand(-40,40),y:H*.8+rand(0,45),vx:rand(-20,20),vy:rand(-140,-50),life:.4,max:.4,color:'#ffd36b',size:rand(2,4)})}updateHud()}}
function frame(now){const dt=Math.min(.04,(now-(last||now))/1000);last=now;update(dt);draw(dt);requestAnimationFrame(frame)}
function bindBoost(button){button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture?.(e.pointerId);setBoost(true)});button.addEventListener('pointerup',()=>setBoost(false));button.addEventListener('pointercancel',()=>setBoost(false));button.addEventListener('lostpointercapture',()=>setBoost(false));button.addEventListener('contextmenu',e=>e.preventDefault())}
bindBoost(ui.boostBtn);bindBoost(ui.mobileBoost);
$('leftBtn').addEventListener('pointerdown',e=>{e.preventDefault();move(-1)});$('rightBtn').addEventListener('pointerdown',e=>{e.preventDefault();move(1)});
ui.pause.addEventListener('click',()=>state==='paused'?resumeGame():pauseGame());
$('soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';e.currentTarget.style.color=soundOn?'#62f0ff':'';if(soundOn)playTone(520,.08)});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright',' ','arrowup'].includes(k))e.preventDefault();if(k==='arrowleft'||k==='a')move(-1);else if(k==='arrowright'||k==='d')move(1);else if(k===' '||k==='arrowup'){if(state==='ready'||state==='over')startGame();else setBoost(true)}else if(k==='escape'||k==='p'){if(state==='playing')pauseGame();else if(state==='paused')resumeGame()}else if(k==='enter'&&(state==='ready'||state==='over'))startGame()});
window.addEventListener('keyup',e=>{if(e.key===' '||e.key==='ArrowUp')setBoost(false)});
let touchStart=null;canvas.addEventListener('pointerdown',e=>{touchStart={x:e.clientX,y:e.clientY,time:Date.now()}});canvas.addEventListener('pointerup',e=>{if(!touchStart||state!=='playing')return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;if(Math.abs(dx)>25&&Math.abs(dx)>Math.abs(dy))move(dx<0?-1:1);else if(Math.abs(dx)<15&&Math.abs(dy)<15){const r=canvas.getBoundingClientRect();move(e.clientX<r.left+r.width/2?-1:1)}touchStart=null});
window.addEventListener('pointerup',()=>setBoost(false));document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pauseGame()});
updateHud();showOverlay('ready');requestAnimationFrame(frame);

